const item = $input.first().json;
const body = item.body || item;

const cleanPhone = String(body.phone || '').replace(/[^0-9]/g, '');
const phoneDisplay = body.phone || 'N/A';
const customerName = body.name || 'Customer';
const route = body.route || 'Tour Inquiry';
const vehicle = body.vehicle || 'Standard Cab / Tour Vehicle';
const travelDate = body.date || 'Flexible';
const travelTime = body.time || '';
const pickup = body.pickup || '';
const drop = body.drop || '';
const passengers = body.passengers || '1';
const bookingId = body.id || ('BK-' + Math.floor(100000 + Math.random() * 900000));
const createdAt = body.createdAt || new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' });

const waLink = cleanPhone ? 'https://wa.me/91' + cleanPhone + '?text=' + encodeURIComponent('Hello ' + customerName + ', thank you for contacting CityCabs24 regarding ' + route + ' (' + bookingId + '). How can we assist you?') : '';

let msg = '🚖 *CityCabs24 - NEW BOOKING ALERT!*\n';
msg += '━━━━━━━━━━━━━━━━━━━━\n';
msg += '👤 *Customer:* ' + customerName + '\n';
msg += '📞 *Phone:* `+91 ' + phoneDisplay + '`\n';
msg += '📍 *Route:* ' + route + '\n';
msg += '🚗 *Vehicle:* ' + vehicle + '\n';
msg += '📅 *Travel Date:* ' + travelDate + (travelTime ? ' ' + travelTime : '') + '\n';
if (pickup) msg += '🚏 *Pickup:* ' + pickup + '\n';
if (drop) msg += '🏁 *Drop:* ' + drop + '\n';
if (passengers && passengers !== '1') msg += '👥 *Passengers:* ' + passengers + '\n';
msg += '🆔 *Booking ID:* `' + bookingId + '`\n';
msg += '⏰ *Received:* ' + createdAt + '\n';
msg += '━━━━━━━━━━━━━━━━━━━━\n';
msg += '⚡ *Contact customer immediately!*';

// Send to Shahrukh Khan Telegram Chat ID
const recipientChatIds = ['8461306899'];

return recipientChatIds.map(chatId => ({
  json: {
    bookingId,
    customerName,
    phone: phoneDisplay,
    cleanPhone,
    route,
    vehicle,
    travelDate,
    travelTime,
    pickup,
    drop,
    passengers,
    createdAt,
    waLink,
    chatId,
    telegramMessage: msg
  }
}));
